function normalizePost(post = {}) {
	return {
		id: String(post.id || ''),
		userId: String(post.userId || post.authorId || post.id || ''),
		authorNickname: String(post.authorNickname || post.authorName || '想法来客'),
		authorAvatarUrl: String(post.authorAvatarUrl || DEFAULT_AVATAR_URL),
		content: String(post.content || ''),
		title: String(post.title || ''),
		tags: Array.isArray(post.tags) ? post.tags.filter(Boolean) : ['日常'],
		images: Array.isArray(post.images) ? post.images : [],
		createdAt: post.createdAt || new Date().toISOString(),
		visibility: 'public_named',
		auditStatus: 'approved',
		favoriteCount: Number(post.favoriteCount || 0),
		commentCount: Number(post.commentCount || 0),
		resonanceCount: Number(post.resonanceCount || 0),
		isFavorited: Boolean(post.isFavorited),
		isResonated: Boolean(post.isResonated),
		comments: Array.isArray(post.comments) ? post.comments : []
	};
}

function readLocalPosts() {
	try {
		const posts = uni.getStorageSync(STORAGE_KEY);
		return Array.isArray(posts) ? posts.map(normalizePost).filter((item) => item.id) : [];
	} catch (error) {
		return [];
	}
}

function writeLocalPosts(posts) {
	try {
		uni.setStorageSync(STORAGE_KEY, posts.slice(0, LOCAL_POST_LIMIT));
	} catch (error) {}
}

function readInteractions() {
	try {
		const interactions = uni.getStorageSync(INTERACTION_STORAGE_KEY);
		return interactions && typeof interactions === 'object' ? interactions : {};
	} catch (error) {
		return {};
	}
}

function writeInteractions(interactions) {
	try {
		uni.setStorageSync(INTERACTION_STORAGE_KEY, interactions);
	} catch (error) {}
}

function applyInteraction(post, interactions = readInteractions()) {
	const state = interactions[post.id] || {};
	return normalizePost({ ...post, ...state });
}

export function listReviewFeedPosts() {
	const interactions = readInteractions();
	return [
		...readLocalPosts(),
		...REVIEW_FEED_SEEDS.map(normalizePost)
	].map((post) => applyInteraction(post, interactions));
}

export function listReviewLocalPosts() {
	const interactions = readInteractions();
	return readLocalPosts().map((post) => applyInteraction(post, interactions));
}

export function getReviewFeedPage(params = {}) {
	const page = Math.max(1, Number(params.page || 1));
	const pageSize = Math.max(1, Number(params.pageSize || 10));
	const posts = listReviewFeedPosts();
	const offset = (page - 1) * pageSize;

	return {
		items: posts.slice(offset, offset + pageSize),
		page,
		pageSize,
		hasMore: offset + pageSize < posts.length
	};
}

export function getReviewFeedPost(id) {
	const normalizedId = String(id || '');
	return listReviewFeedPosts().find((item) => item.id === normalizedId) || null;
}

export function createReviewFeedPost(payload = {}, author = {}) {
	const post = normalizePost({
		...payload,
		id: `review_local_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
		userId: author.id || 'review_current_user',
		authorNickname: author.nickname || author.name || '我',
		authorAvatarUrl: author.avatarUrl || DEFAULT_AVATAR_URL,
		createdAt: new Date().toISOString()
	});
	writeLocalPosts([post, ...readLocalPosts()]);
	return post;
}

export function updateReviewFeedPost(id, updates = {}) {
	const normalizedId = String(id || '');
	if (!normalizedId) return null;
	const interactions = readInteractions();
	interactions[normalizedId] = { ...(interactions[normalizedId] || {}), ...updates };
	writeInteractions(interactions);
	return getReviewFeedPost(normalizedId);
}

export function toggleReviewFeedFavorite(id) {
	const post = getReviewFeedPost(id);
	if (!post) return null;
	const isFavorited = !post.isFavorited;
	return updateReviewFeedPost(id, {
		isFavorited,
		favoriteCount: Math.max(0, Number(post.favoriteCount || 0) + (isFavorited ? 1 : -1))
	});
}

export function toggleReviewFeedResonance(id) {
	const post = getReviewFeedPost(id);
	if (!post) return null;
	const isResonated = !post.isResonated;
	return updateReviewFeedPost(id, {
		isResonated,
		resonanceCount: Math.max(0, Number(post.resonanceCount || 0) + (isResonated ? 1 : -1))
	});
}

export function deleteReviewFeedPost(id) {
	const normalizedId = String(id || '');
	writeLocalPosts(readLocalPosts().filter((post) => post.id !== normalizedId));
	const interactions = readInteractions();
	delete interactions[normalizedId];
	writeInteractions(interactions);
}
